}

import { SortableItem, type AIProcessedItem } from "@/features/requisicoes/ui/SortableItem";

import { useProductAliases, normalizeAlias } from "@/features/produtos/model/useProductAliases";

export default function Requisicao() {
  const { selectedStore } = useStore();
  const SESSIONS_DISABLED = true;
  const navigate = useNavigate();
  const location = useLocation();
  const isAgenteRepa = location.pathname === '/agente-repa';
  const isInSession = false as boolean;
  const globalSessionId = null as string | null;
  const exitSession = () => { };
  const enterSession = (_id?: string) => { };
  const { userProfile } = useAuth();
  const isMobile = useIsMobile();
  const isTablet = useIsTablet();
  const { isAdmin, canViewRequisicao } = usePermissions();
  const isLogistica = false;

  // Hook para aliases de produtos (aprendizado contínuo)
  const { addAlias, findProductByAlias, fetchAliases } = useProductAliases();

  const [manualRequestText, setManualRequestText] = useState("");
  const [allItems, setAllItems] = useState<AIProcessedItem[]>([]);
  // Manual Matching States
  const [isMatchModalOpen, setIsMatchModalOpen] = useState(false);
  const [unmatchedItems, setUnmatchedItems] = useState<AIProcessedItem[]>([]);

  const [synthesizerReview, setSynthesizerReview] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStage, setProcessingStage] = useState('');
  const [processingProgress, setProcessingProgress] = useState(0);
  const [aiReasoningLive, setAiReasoningLive] = useState<string[]>([]);
  // Erro persistente do processamento manual (banner na aba de input) — não some como o toast.
  const [processingError, setProcessingError] = useState<string | null>(null);
  // Controla o abort do streaming da IA (botão Cancelar + watchdog de inatividade).
  const aiAbortRef = useRef<AbortController | null>(null);

  // Initialize with user profile data if available
  const [requesterName, setRequesterName] = useState(userProfile?.nome || "Colaborador");
  const [preparerName, setPreparerName] = useState("DAVI/PEDRO");
  const [storeRequester, setStoreRequester] = useState(userProfile?.unidade || userProfile?.metadata?.store_name || "ASA NORTE");
  const [storePreparer, setStorePreparer] = useState("Fábrica");
  const [orderDate, setOrderDate] = useState(getCurrentLocalDate());
  const [receivedDate, setReceivedDate] = useState(() => getTomorrowLocalDate());

  // Update effect for profile changes
  useEffect(() => {
    if (userProfile) {
      if (userProfile.nome) setRequesterName(userProfile.nome);
      if (userProfile.unidade) setStoreRequester(userProfile.unidade);
    }
  }, [userProfile]);
  const [showHistory, setShowHistory] = useState(false);
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [historyFilter, setHistoryFilter] = useState<'all' | 'aprovada' | 'em_fila' | 'pendente' | 'rejeitada'>('em_fila');
  const [showReportsModal, setShowReportsModal] = useState(false);
  const [showActiveSeparationsModal, setShowActiveSeparationsModal] = useState(false);
  const [isLeaving, setIsLeaving] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [flowSource, setFlowSource] = useState<'auto' | 'text' | 'manual' | null>(isAgenteRepa ? 'auto' : null);

  // Expedition Tracker State
  const [showExpeditionTracker, setShowExpeditionTracker] = useState(false);
  const [activeExpeditionId, setActiveExpeditionId] = useState<string | null>(null);
  const [trackerStoreName, setTrackerStoreName] = useState<string>('');
  const [availableExpeditions, setAvailableExpeditions] = useState<any[]>([]);
  const [showExpeditionSelector, setShowExpeditionSelector] = useState(false);

  const handleCheckExpedition = async () => {
    try {
      // Find ALL active expeditions
      const { data: exps, error } = await supabase
        .from('expedicoes')
        .select('id, status, code, veiculo, created_at, requisicoes(count)')
        .in('status', ['separation', 'loading', 'dispatch', 'in_transit', 'unloading'])
        .order('created_at', { ascending: false });

      if (error) throw error;

      if (exps && exps.length > 0) {
        // ALWAYS show selector, even if there is only one
        setAvailableExpeditions(exps);
        setShowExpeditionSelector(true);
      } else {
        toast.info("Nenhuma expedição em andamento encontrada.");
      }
    } catch (e) {
      handleError(e, { domain: 'requisicoes', operation: 'checarExpedicao', showToast: false });
      toast.error("Erro ao buscar expedições.");
    }
  };

  const handleSelectExpedition = (expeditionId: string) => {
    setActiveExpeditionId(expeditionId);
    setTrackerStoreName(storeRequester || "Asa Sul");
    setShowExpeditionSelector(false);
    setShowExpeditionTracker(true);
  };

  // Auto AI States

  const [isWizardMode, setIsWizardMode] = useState(isAgenteRepa);
  const [loadingAutoAi, setLoadingAutoAi] = useState(false);
  // const [showAutoAiDateModal, setShowAutoAiDateModal] = useState(false); // Removed in favor of wizard
  const [loadingWordsIndex, setLoadingWordsIndex] = useState(0);
  const loadingWords = [
    "Analisando histórico de vendas...",
    "Verificando níveis de estoque...",
    "Calculando sugestão matemática...",
    "Aplicando regras de negócios...",
    "Consultando padrões de consumo...",
    "Gerando decisões executivas..."
  ];

  useEffect(() => {
    if (loadingAutoAi) {
      const interval = setInterval(() => {
        setLoadingWordsIndex((prev) => (prev + 1) % loadingWords.length);
      }, 2000);
      return () => clearInterval(interval);
    }
  }, [loadingAutoAi]);
  const [activeSeparations, setActiveSeparations] = useState<ActiveSeparation[]>([]);
  const [activeReviewSessions, setActiveReviewSessions] = useState<ActiveReviewSession[]>([]);
  const [loadingActiveSeparations, setLoadingActiveSeparations] = useState(false);
  // Estado do modal de Fila
  const [showQueueModal, setShowQueueModal] = useState(false);
  const [queueLoading, setQueueLoading] = useState(false);
  const [queueItems, setQueueItems] = useState<any[]>([]);
  // Estado para controlar se está na etapa de entrega
  const [isDeliveryStep, setIsDeliveryStep] = useState(false);
  // Estado para controlar a direção da animação (entrada/saída)
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [transitionDirection, setTransitionDirection] = useState<'forward' | 'backward'>('forward');
  const [savedLists, setSavedLists] = useState<Array<{
    id: number;
    name: string;
    items: AIProcessedItem[];
    createdAt: string;
    requesterName: string;
    preparerName: string;
    storeRequester: string;
    storePreparer: string;
    orderDate: string;
    receivedDate: string;
    subtitle?: string;

