// Expedition Tracker State
const [showExpeditionTracker, setShowExpeditionTracker] = useState(false);
const [activeExpeditionId, setActiveExpeditionId] = useState<string | null>(null);
const [trackerStoreName, setTrackerStoreName] = useState<string>('');
const [availableExpeditions, setAvailableExpeditions] = useState<any[]>([]);
const [showExpeditionSelector, setShowExpeditionSelector] = useState(false);

const handleCheckExpedition = async () => {
  try {
    // Find ALL active expeditions
    const { data: exps, error } = await supabase
      .from('expedicoes')
      .select('id, status, code, veiculo, created_at, requisicoes(count)')
      .in('status', ['separation', 'loading', 'dispatch', 'in_transit', 'unloading'])
      .order('created_at', { ascending: false });

    if (error) throw error;

    if (exps && exps.length > 0) {
      // ALWAYS show selector, even if there is only one
      setAvailableExpeditions(exps);
      setShowExpeditionSelector(true);
    } else {
      toast.info("Nenhuma expedição em andamento encontrada.");
    }
  } catch (e) {
    handleError(e, { domain: 'requisicoes', operation: 'checarExpedicao', showToast: false });
    toast.error("Erro ao buscar expedições.");
  }
};

const handleSelectExpedition = (expeditionId: string) => {
  setActiveExpeditionId(expeditionId);
  setTrackerStoreName(storeRequester || "Asa Sul");
  setShowExpeditionSelector(false);
  setShowExpeditionTracker(true);
};

// Auto AI States

